import fs from 'node:fs';
import path from 'node:path';
import { parseEvidenceLedger } from '@featherduster/core';

/**
 * True when a file holds a consolidated evidence ledger (many entries). These files
 * must never be overwritten with a single serialized entry.
 */
export function isConsolidatedLedgerFile(file: string): boolean {
  if (path.basename(file).toLowerCase().startsWith('evidence-ledger')) return true;
  if (!fs.existsSync(file)) return false;
  try {
    const content = fs.readFileSync(file, 'utf-8');
    if (!content.includes('entries:')) return false;
    return parseEvidenceLedger(content, file).length > 0;
  } catch {
    return false;
  }
}

export function toWorkspaceRelative(workspaceDir: string, file: string): string {
  return path.relative(workspaceDir, file).replace(/\\/g, '/');
}

export function isInsideWorkspace(workspaceDir: string, file: string): boolean {
  const rel = path.relative(path.resolve(workspaceDir), path.resolve(file));
  return !rel.startsWith('..') && !path.isAbsolute(rel);
}

import type { Context, Hono, MiddlewareHandler } from 'hono';
import { ZodError } from 'zod';
import { loadTailoringConfig } from '../tailoring/config.js';
import type { RunnerFactory } from '../runners/registry.js';
import type { RunnerId } from '../runners/types.js';
import {
  ANTHROPIC_KEY_ACCOUNT,
  CredentialStoreError,
  summarizeAnthropicCredential,
  validateAnthropicKeyShape,
  type CredentialStore,
} from './credentials.js';
import { RunnerSettingsPatchSchema, revokeRunnerConsent, writeRunnerSettings } from './runner-settings.js';
import type { ClaudeAuthManager, LoginMode } from './claude-auth.js';
import type { CodexAuthManager } from './codex-auth.js';

export interface SettingsRouteDeps {
  workspaceDir: string;
  store: () => CredentialStore;
  claudeAuth: ClaudeAuthManager;
  codexAuth: CodexAuthManager;
  runnerFactory: RunnerFactory;
  env?: NodeJS.ProcessEnv;
  fetchImpl?: typeof fetch;
}

const TESTABLE: RunnerId[] = ['claude-code', 'codex', 'anthropic-api', 'ollama'];

/** Mutations must be JSON: blocks form-encoded cross-site requests in addition to the origin checks. */
const requireJson: MiddlewareHandler = async (c, next) => {
  if (['POST', 'PUT', 'DELETE'].includes(c.req.method)) {
    const type = c.req.header('content-type') ?? '';
    if (!type.toLowerCase().startsWith('application/json')) {
      return c.json({ error: 'Settings changes require a JSON request.', code: 'unsupported_media_type' }, 415);
    }
  }
  await next();
};

async function body(c: Context): Promise<any> {
  try {
    return await c.req.json();
  } catch {
    return {};
  }
}

export function mountSettingsRoutes(app: Hono, deps: SettingsRouteDeps): void {
  const env = () => deps.env ?? process.env;

  const snapshot = () => {
    const config = loadTailoringConfig(deps.workspaceDir);
    return {
      runner: config.runner,
      runner_consent: config.runner_consent,
      deslop_warn_band: config.deslop_warn_band,
      credentials: { anthropic: summarizeAnthropicCredential(env(), deps.store()) },
    };
  };

  app.use('/api/settings/*', requireJson);

  app.get('/api/settings', (c) => c.json(snapshot()));

  app.put('/api/settings/runner', async (c) => {
    try {
      const patch = RunnerSettingsPatchSchema.parse(await body(c));
      writeRunnerSettings(deps.workspaceDir, patch);
      return c.json(snapshot());
    } catch (err) {
      if (err instanceof ZodError) {
        return c.json({ error: err.issues.map((i) => `${i.path.join('.')}: ${i.message}`).join('; '), code: 'invalid' }, 400);
      }
      return c.json({ error: err instanceof Error ? err.message : 'Failed to save settings', code: 'write_failed' }, 500);
    }
  });

  app.put('/api/settings/credentials/anthropic', async (c) => {
    const { apiKey } = await body(c);
    const problem = validateAnthropicKeyShape(apiKey);
    if (problem) return c.json({ error: problem, code: 'invalid_key' }, 400);
    try {
      deps.store().set(ANTHROPIC_KEY_ACCOUNT, String(apiKey).trim());
    } catch (err) {
      const message = err instanceof CredentialStoreError ? err.message : 'Could not save the key.';
      return c.json({ error: message, code: 'store_unavailable' }, 503);
    }
    return c.json(snapshot());
  });

  app.delete('/api/settings/credentials/anthropic', (c) => {
    deps.store().delete(ANTHROPIC_KEY_ACCOUNT);
    return c.json(snapshot());
  });

  app.delete('/api/settings/consent/:runner', (c) => {
    const runner = c.req.param('runner');
    if (!TESTABLE.includes(runner as RunnerId)) return c.json({ error: 'Unknown runner', code: 'invalid_runner' }, 400);
    revokeRunnerConsent(deps.workspaceDir, runner);
    return c.json(snapshot());
  });

  app.post('/api/settings/runners/:id/test', async (c) => {
    const id = c.req.param('id') as RunnerId;
    if (!TESTABLE.includes(id)) return c.json({ error: 'Unknown runner', code: 'invalid_runner' }, 400);
    const runner = deps.runnerFactory(id, loadTailoringConfig(deps.workspaceDir).runner);
    if (!runner) return c.json({ available: false, detail: 'Runner unavailable' });
    return c.json(await runner.detect());
  });

  app.get('/api/settings/ollama/models', async (c) => {
    const url = (c.req.query('url') || loadTailoringConfig(deps.workspaceDir).runner.ollama.url).replace(/\/+$/, '');
    if (!/^https?:\/\//.test(url)) return c.json({ error: 'Invalid URL', code: 'invalid_url' }, 400);
    try {
      const res = await (deps.fetchImpl ?? fetch)(`${url}/api/tags`, { signal: AbortSignal.timeout(3000) });
      if (!res.ok) return c.json({ reachable: false, models: [], detail: `Ollama responded ${res.status}` });
      const data = (await res.json()) as { models?: Array<{ name: string }> };
      return c.json({ reachable: true, models: (data.models ?? []).map((m) => m.name).sort(), detail: `Ollama at ${url}` });
    } catch {
      return c.json({ reachable: false, models: [], detail: `Ollama is not running at ${url}.` });
    }
  });

  app.get('/api/settings/claude-code/auth', (c) =>
    c.json({ status: deps.claudeAuth.status(), login: deps.claudeAuth.loginJob })
  );

  app.post('/api/settings/claude-code/login', async (c) => {
    const { mode } = await body(c);
    const loginMode: LoginMode = mode === 'console' ? 'console' : 'claudeai';
    return c.json({ login: deps.claudeAuth.startLogin(loginMode) }, 202);
  });

  app.post('/api/settings/claude-code/login/cancel', (c) => c.json({ login: deps.claudeAuth.cancelLogin() }));

  app.post('/api/settings/claude-code/logout', (c) => {
    const result = deps.claudeAuth.logout();
    return c.json({ ...result, status: deps.claudeAuth.status() }, result.ok ? 200 : 500);
  });

  app.get('/api/settings/codex/auth', (c) => c.json({ status: deps.codexAuth.status(), login: deps.codexAuth.loginJob }));

  app.post('/api/settings/codex/login', async (c) => {
    const { mode } = await body(c);
    return c.json({ login: deps.codexAuth.startLogin(mode === 'device' ? 'device' : 'chatgpt') }, 202);
  });

  app.post('/api/settings/codex/login/cancel', (c) => c.json({ login: deps.codexAuth.cancelLogin() }));

  app.post('/api/settings/codex/api-key', async (c) => {
    const { apiKey } = await body(c);
    if (typeof apiKey !== 'string' || apiKey.trim().length < 20 || /\s/.test(apiKey.trim())) {
      return c.json({ error: 'That does not look like a complete OpenAI API key.', code: 'invalid_key' }, 400);
    }
    const result = deps.codexAuth.loginWithApiKey(apiKey.trim());
    return c.json({ ...result, status: deps.codexAuth.status() }, result.ok ? 200 : 502);
  });

  app.post('/api/settings/codex/logout', (c) => {
    const result = deps.codexAuth.logout();
    return c.json({ ...result, status: deps.codexAuth.status() }, result.ok ? 200 : 500);
  });
}

import type { Context, Hono } from 'hono';
import { RunStoreError } from './store.js';
import { TailoringError, type TailoringOrchestrator } from './orchestrator.js';

function handleError(c: Context, err: unknown) {
  if (err instanceof TailoringError) {
    return c.json({ error: err.message, code: err.code, detail: err.detail }, err.status as any);
  }
  if (err instanceof RunStoreError) {
    return c.json({ error: err.message, code: 'store' }, err.status as any);
  }
  return c.json({ error: err instanceof Error ? err.message : 'Unexpected error', code: 'internal' }, 500);
}

async function readJson(c: Context): Promise<any> {
  try {
    return await c.req.json();
  } catch {
    return {};
  }
}

/** Mounts /api/runners and /api/tailoring/* on the app. */
export function mountTailoringRoutes(app: Hono, orchestrator: TailoringOrchestrator): void {
  app.get('/api/runners', async (c) => {
    try {
      return c.json(await orchestrator.runners());
    } catch (err) {
      return handleError(c, err);
    }
  });

  app.post('/api/runners/consent', async (c) => {
    try {
      const body = await readJson(c);
      orchestrator.recordConsent(body.runner);
      return c.json({ success: true });
    } catch (err) {
      return handleError(c, err);
    }
  });

  app.get('/api/tailoring-citations', (c) => {
    try {
      return c.json(orchestrator.citationIndex());
    } catch (err) {
      return handleError(c, err);
    }
  });

  app.get('/api/tailoring', (c) => {
    try {
      return c.json({ runs: orchestrator.listRuns() });
    } catch (err) {
      return handleError(c, err);
    }
  });

  app.post('/api/tailoring', async (c) => {
    try {
      const body = await readJson(c);
      const manifest = orchestrator.createRun(body);
      return c.json({ slug: manifest.slug, manifest }, 201);
    } catch (err) {
      return handleError(c, err);
    }
  });

  app.get('/api/tailoring/:slug', (c) => {
    try {
      return c.json(orchestrator.getRun(c.req.param('slug')));
    } catch (err) {
      return handleError(c, err);
    }
  });

  app.post('/api/tailoring/:slug/steps/:step/run', async (c) => {
    try {
      const result = await orchestrator.startStep(c.req.param('slug'), c.req.param('step'));
      return c.json(result, 202);
    } catch (err) {
      return handleError(c, err);
    }
  });

  app.get('/api/tailoring/:slug/steps/:step/preview', (c) => {
    try {
      return c.json(orchestrator.previewInput(c.req.param('slug'), c.req.param('step')));
    } catch (err) {
      return handleError(c, err);
    }
  });

  app.put('/api/tailoring/:slug/steps/:step', async (c) => {
    try {
      const body = await readJson(c);
      return c.json(orchestrator.saveStep(c.req.param('slug'), c.req.param('step'), body));
    } catch (err) {
      return handleError(c, err);
    }
  });

  app.post('/api/tailoring/:slug/steps/:step/approve', (c) => {
    try {
      return c.json(orchestrator.approveStep(c.req.param('slug'), c.req.param('step')));
    } catch (err) {
      return handleError(c, err);
    }
  });

  app.post('/api/tailoring/:slug/cancel', (c) => {
    try {
      return c.json(orchestrator.cancel(c.req.param('slug')));
    } catch (err) {
      return handleError(c, err);
    }
  });

  app.post('/api/tailoring/:slug/finalize', (c) => {
    try {
      return c.json(orchestrator.finalize(c.req.param('slug')));
    } catch (err) {
      return handleError(c, err);
    }
  });
}

import fs from 'node:fs';
import path from 'node:path';
import yaml from 'js-yaml';
import { RunManifestSchema, type RunManifest } from '@featherduster/core';

export const TAILORING_DIR = 'tailoring';
const SLUG_RE = /^[a-z0-9][a-z0-9-]{0,79}$/;

export const RUN_FILES = {
  manifest: 'run.yaml',
  posting: 'job-posting.md',
  analysis: 'analysis.json',
  alignment: 'alignment.json',
  proposals: 'proposals.json',
  resume: 'resume.yaml',
  brief: 'brief.md',
  briefData: 'brief.json',
} as const;
export type RunFile = (typeof RUN_FILES)[keyof typeof RUN_FILES];

export class RunStoreError extends Error {
  readonly status: number;
  constructor(status: number, message: string) {
    super(message);
    this.name = 'RunStoreError';
    this.status = status;
  }
}

export function isValidSlug(slug: string): boolean {
  return SLUG_RE.test(slug);
}

export function slugify(label: string): string {
  return label
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 60)
    .replace(/-+$/g, '');
}

function timestampSlug(date: Date): string {
  const pad = (n: number) => String(n).padStart(2, '0');
  return `run-${date.getFullYear()}${pad(date.getMonth() + 1)}${pad(date.getDate())}-${pad(date.getHours())}${pad(date.getMinutes())}${pad(date.getSeconds())}`;
}

/** Filesystem persistence for tailoring runs under `<workspace>/tailoring/<slug>/`. */
export class RunStore {
  readonly rootDir: string;

  constructor(workspaceDir: string) {
    this.rootDir = path.join(path.resolve(workspaceDir), TAILORING_DIR);
  }

  runDir(slug: string): string {
    if (!isValidSlug(slug)) throw new RunStoreError(400, `Invalid run slug "${slug}"`);
    const dir = path.join(this.rootDir, slug);
    const rel = path.relative(this.rootDir, dir);
    if (rel.startsWith('..') || path.isAbsolute(rel)) throw new RunStoreError(403, 'Path traversal detected');
    return dir;
  }

  private filePath(slug: string, file: RunFile): string {
    const full = path.join(this.runDir(slug), file);
    if (fs.existsSync(full) && fs.lstatSync(full).isSymbolicLink()) {
      throw new RunStoreError(403, 'Refusing to read or write symbolic links');
    }
    return full;
  }

  exists(slug: string): boolean {
    return isValidSlug(slug) && fs.existsSync(path.join(this.rootDir, slug, RUN_FILES.manifest));
  }

  allocateSlug(label: string | undefined, now: Date): string {
    const base = (label && slugify(label)) || timestampSlug(now);
    const safeBase = isValidSlug(base) ? base : timestampSlug(now);
    let slug = safeBase;
    let n = 2;
    while (fs.existsSync(path.join(this.rootDir, slug))) {
      slug = `${safeBase.slice(0, 74)}-${n++}`;
    }
    return slug;
  }

  create(slug: string): void {
    const dir = this.runDir(slug);
    if (fs.existsSync(dir)) throw new RunStoreError(409, `Run "${slug}" already exists`);
    fs.mkdirSync(dir, { recursive: true });
  }

  readManifest(slug: string): RunManifest {
    const file = this.filePath(slug, RUN_FILES.manifest);
    if (!fs.existsSync(file)) throw new RunStoreError(404, `Run "${slug}" not found`);
    return RunManifestSchema.parse(yaml.load(fs.readFileSync(file, 'utf-8')));
  }

  writeManifest(manifest: RunManifest): void {
    const validated = RunManifestSchema.parse(manifest);
    this.writeAtomic(this.filePath(validated.slug, RUN_FILES.manifest), yaml.dump(validated, { indent: 2, lineWidth: 120 }));
  }

  readText(slug: string, file: RunFile): string | null {
    const full = this.filePath(slug, file);
    return fs.existsSync(full) ? fs.readFileSync(full, 'utf-8') : null;
  }

  writeText(slug: string, file: RunFile, content: string): void {
    this.writeAtomic(this.filePath(slug, file), content);
  }

  readJson<T>(slug: string, file: RunFile, parse: (raw: unknown) => T): T | null {
    const text = this.readText(slug, file);
    if (text === null) return null;
    try {
      return parse(JSON.parse(text));
    } catch {
      return null;
    }
  }

  writeJson(slug: string, file: RunFile, data: unknown): void {
    this.writeText(slug, file, JSON.stringify(data, null, 2) + '\n');
  }

  list(): RunManifest[] {
    if (!fs.existsSync(this.rootDir)) return [];
    const manifests: RunManifest[] = [];
    for (const entry of fs.readdirSync(this.rootDir, { withFileTypes: true })) {
      if (!entry.isDirectory() || !isValidSlug(entry.name)) continue;
      try {
        manifests.push(this.readManifest(entry.name));
      } catch {
        // skip malformed runs
      }
    }
    return manifests.sort((a, b) => b.updated.localeCompare(a.updated));
  }

  private writeAtomic(file: string, content: string): void {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    const tmp = `${file}.${process.pid}.tmp`;
    fs.writeFileSync(tmp, content, 'utf-8');
    try {
      fs.renameSync(tmp, file);
    } catch {
      // Windows can refuse rename over a file held open by a watcher; fall back to direct write.
      fs.writeFileSync(file, content, 'utf-8');
      fs.rmSync(tmp, { force: true });
    }
  }
}

import type { NavTab } from './components/Layout';

/** The manual canvas is a mode of the tailor tab, not a run slug. */
export const CANVAS_PATH = '/tailor/canvas';

/** Reserved `/tailor/*` segments that never name a run. */
const RESERVED_TAILOR_SEGMENTS = new Set(['canvas']);

const routeByTab: Record<NavTab, string> = {
  briefing: '/briefing',
  threads: '/threads',
  evidence: '/evidence',
  skills: '/skills',
  tailor: '/tailor',
  settings: '/settings',
};

const tabByRoute: Record<string, NavTab> = {
  '/': 'briefing',
  '/briefing': 'briefing',
  '/threads': 'threads',
  '/evidence': 'evidence',
  '/skills': 'skills',
  '/rubrics': 'skills',
  '/tailor': 'tailor',
  '/settings': 'settings',
};

/** Paths that moved when tailoring and exports merged into one tab. */
const legacyRoutes: Record<string, string> = {
  '/exports': CANVAS_PATH,
};

function normalize(pathname: string): string {
  return pathname.length > 1 ? pathname.replace(/\/+$/, '') : pathname;
}

/** Canonical path for a legacy URL, or null when the path is already current. */
export function redirectForPath(pathname: string): string | null {
  return legacyRoutes[normalize(pathname)] ?? null;
}

export function pathForTab(tab: NavTab): string {
  return routeByTab[tab];
}

export function tabForPath(pathname: string): NavTab {
  const normalized = normalize(pathname);
  if (legacyRoutes[normalized]) return tabForPath(legacyRoutes[normalized]);
  if (normalized.startsWith('/tailor/')) return 'tailor';
  return tabByRoute[normalized] ?? 'briefing';
}

/** Run slug for `/tailor/<slug>` paths, else null. */
export function tailoringSlugForPath(pathname: string): string | null {
  const match = /^\/tailor\/([a-z0-9][a-z0-9-]{0,79})\/?$/.exec(pathname);
  if (!match) return null;
  return RESERVED_TAILOR_SEGMENTS.has(match[1]) ? null : match[1];
}

/** Which of the tailor tab's three modes a path selects. */
export type TailorView =
  | { mode: 'list' }
  | { mode: 'run'; slug: string }
  | { mode: 'canvas' };

export function tailorViewForPath(pathname: string): TailorView {
  const normalized = normalize(pathname);
  const canonical = legacyRoutes[normalized] ?? normalized;
  if (canonical === CANVAS_PATH) return { mode: 'canvas' };
  const slug = tailoringSlugForPath(canonical);
  return slug ? { mode: 'run', slug } : { mode: 'list' };
}

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import yaml from 'js-yaml';
import { createApp } from '../src/server.js';
import { WorkspaceWatcher } from '../src/watcher.js';
import {
  ANTHROPIC_KEY_ACCOUNT,
  MemoryCredentialStore,
  UnavailableCredentialStore,
  resolveAnthropicCredential,
  summarizeAnthropicCredential,
  type CredentialStore,
} from '../src/settings/credentials.js';
import { writeRunnerSettings, revokeRunnerConsent } from '../src/settings/runner-settings.js';
import { ClaudeAuthManager } from '../src/settings/claude-auth.js';
import { AnthropicApiRunner } from '../src/runners/anthropic-api.js';
import type { RunnerFactory } from '../src/runners/registry.js';

const here = path.dirname(fileURLToPath(import.meta.url));
const fakeClaude = path.join(here, 'fixtures', 'fake-claude.mjs');
const KEY = 'sk-ant-api03-test-key-000000000000wxyz';

const CONFIG_WITH_COMMENTS = `# Workspace config — keep this comment
active_profile: sample-company
default_export_target: markdown
port: 4173
runner:
  default: claude-code # preferred runner
  step_timeout_seconds: 180
  claude-code:
    model: ""
  anthropic-api:
    model: claude-opus-5
  ollama:
    url: http://127.0.0.1:11434
    model: ""
    max_context: 32768
runner_consent:
  claude-code: '2026-09-16'
  anthropic-api: '2026-09-16'
`;

function authManager(env: NodeJS.ProcessEnv = {}) {
  return new ClaudeAuthManager({ command: process.execPath, prefixArgs: [fakeClaude], env: { ...process.env, ...env }, loginTimeoutMs: 5000 });
}

async function waitFor<T>(fn: () => T | Promise<T>, ok: (v: T) => boolean, ms = 5000): Promise<T> {
  const start = Date.now();
  for (;;) {
    const v = await fn();
    if (ok(v)) return v;
    if (Date.now() - start > ms) throw new Error(`timed out: ${JSON.stringify(v)}`);
    await new Promise((r) => setTimeout(r, 50));
  }
}

describe('credential resolution', () => {
  it('prefers env over the keychain and never exposes more than last4', () => {
    const store = new MemoryCredentialStore();
    store.set(ANTHROPIC_KEY_ACCOUNT, KEY);
    expect(resolveAnthropicCredential({}, store)).toEqual({ key: KEY, source: 'keychain' });
    expect(resolveAnthropicCredential({ ANTHROPIC_API_KEY: 'env-key-1234567890' }, store)?.source).toBe('env');
    const summary = summarizeAnthropicCredential({ ANTHROPIC_API_KEY: 'env-key-1234567890' }, store);
    expect(summary).toMatchObject({ configured: true, source: 'env', envVar: 'ANTHROPIC_API_KEY', last4: '7890', shadowedKeychainValue: true });
    expect(JSON.stringify(summary)).not.toContain('env-key');
  });

  it('reports an unavailable store without throwing on read', () => {
    const store = new UnavailableCredentialStore('no secret service');
    expect(summarizeAnthropicCredential({}, store)).toMatchObject({ configured: false, storeAvailable: false, storeDetail: 'no secret service' });
    expect(() => store.set(ANTHROPIC_KEY_ACCOUNT, KEY)).toThrow(/unavailable/);
  });
});

describe('runner settings writer', () => {
  let ws: string;
  beforeEach(() => {
    ws = fs.mkdtempSync(path.join(os.tmpdir(), 'fd-settings-'));
    fs.mkdirSync(path.join(ws, '.featherduster'));
    fs.writeFileSync(path.join(ws, '.featherduster', 'config.yaml'), CONFIG_WITH_COMMENTS);
  });
  afterEach(() => fs.rmSync(ws, { recursive: true, force: true }));

  it('patches values while preserving comments and unrelated keys', () => {
    writeRunnerSettings(ws, { default: 'ollama', ollama: { model: 'llama3.1:8b' }, deslop_warn_band: 'high' });
    const text = fs.readFileSync(path.join(ws, '.featherduster', 'config.yaml'), 'utf-8');
    expect(text).toContain('# Workspace config — keep this comment');
    expect(text).toContain('# preferred runner');
    const parsed = yaml.load(text) as any;
    expect(parsed.runner.default).toBe('ollama');
    expect(parsed.runner.ollama).toEqual({ url: 'http://127.0.0.1:11434', model: 'llama3.1:8b', max_context: 32768 });
